package com.nigson.commerce.pricing;
import java.util.*;
import java.time.Instant;
import java.math.BigDecimal;
import org.springframework.jdbc.core.JdbcTemplate;
import com.nigson.shared.problem.*;
/** Approved offered revision is the only override. Catalogue re-pricing never rewrites its agreed amounts. */
public final class JdbcFrozenPrices implements FrozenPrices {
 private final JdbcTemplate jdbc;private final int phase;public JdbcFrozenPrices(JdbcTemplate jdbc,int phase){this.jdbc=jdbc;this.phase=phase;}
 private record Header(UUID quote,long revision,Instant until,BigDecimal total){}
 public Offer require(UUID revision,UUID party,UUID organization,UUID market,Map<UUID,BigDecimal> quantities,Instant now){if(phase<3)throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);var headers=jdbc.query("SELECT q.id,r.revision,r.valid_until,r.total FROM commerce.quote q JOIN commerce.quote_revision r ON r.quote_id=q.id WHERE r.id=? AND q.current_revision_id=r.id AND q.party_id=? AND q.organization_id IS NOT DISTINCT FROM ?::uuid AND q.market_id=? AND q.status='OFFERED' AND q.accepted_order_id IS NULL AND r.approval_status='APPROVED' AND r.approved_by IS NOT NULL AND r.currency_code='NGN' AND r.valid_until>? FOR SHARE OF q,r",(r,n)->new Header(r.getObject(1,UUID.class),r.getLong(2),r.getTimestamp(3).toInstant(),r.getBigDecimal(4)),revision,party,organization,market,java.sql.Timestamp.from(now));if(headers.size()!=1)throw PricingValues.rule();var lines=jdbc.query("SELECT sku_id,quantity,agreed_unit_amount,discount_amount,tax_amount FROM commerce.quote_line WHERE revision_id=? ORDER BY sku_id LIMIT 101 FOR SHARE",(r,n)->new Line(r.getObject(1,UUID.class),r.getBigDecimal(2),r.getBigDecimal(3),r.getBigDecimal(4),r.getBigDecimal(5)),revision);if(lines.isEmpty()||lines.size()!=quantities.size()||lines.size()>100)throw PricingValues.rule();var seen=new HashSet<UUID>();BigDecimal total=BigDecimal.ZERO;for(var line:lines){BigDecimal expected=quantities.get(line.skuId());if(!seen.add(line.skuId())||expected==null||line.quantity().compareTo(expected)!=0)throw PricingValues.rule();BigDecimal unit=PricingValues.minor(PricingValues.decimal(line.unitAmount()),2),discount=PricingValues.minor(PricingValues.decimal(line.discount()),2),tax=PricingValues.minor(PricingValues.decimal(line.tax()),2);BigDecimal base=PricingValues.rounded(line.quantity().multiply(unit),2);if(discount.compareTo(base)>0)throw PricingValues.rule();total=total.add(base.subtract(discount).add(tax));}var h=headers.getFirst();if(total.compareTo(h.total())!=0)throw PricingValues.rule();return new Offer(h.quote(),revision,h.revision(),h.until(),List.copyOf(lines));}
}
